use super::arithmetic::power2::{
    pow2,
    lemma_pow2_unfold,
    lemma_pow2_adds,
    lemma_pow2_pos,
    lemma2_to64,
    lemma2_to64_rest,
    lemma_pow2_strictly_increases,
};
#[cfg(verus_keep_ghost)]
use super::arithmetic::div_mod::{
    lemma_div_by_multiple,
    lemma_div_denominator,
    lemma_div_is_ordered,
    lemma_mod_breakdown,
    lemma_mod_multiples_vanish,
    lemma_remainder_lower,
};
#[cfg(verus_keep_ghost)]
use super::arithmetic::mul::{
    lemma_mul_inequality,
    lemma_mul_is_commutative,
    lemma_mul_is_associative,
};
#[cfg(verus_keep_ghost)]
use super::calc_macro::*;

} // verus!
// Proofs that shift right is equivalent to division by power of 2.
macro_rules! lemma_shr_is_div {
    ($name:ident, $uN:ty) => {
        #[cfg(verus_keep_ghost)]
        verus! {
        #[doc = "Proof that for x and n of type "]
        #[doc = stringify!($uN)]
        #[doc = ", shifting x right by n is equivalent to division of x by 2^n."]
        pub broadcast proof fn $name(x: $uN, shift: $uN)
            requires
                0 <= shift < <$uN>::BITS,
            ensures
                #[trigger] (x >> shift) == x as nat / pow2(shift as nat),
            decreases shift,
        {
            // Step by 4 to reduce recursion depth (divisor 16 fits in all unsigned types).
            reveal(pow);
            if shift == 0 {
                assert(x >> 0 == x) by (bit_vector);
                assert(pow2(0) == 1) by (compute_only);
            } else if shift == 1 {
                assert(x >> 1 == x / 2) by (bit_vector);
                assert(pow2(1) == 2) by (compute_only);
            } else if shift == 2 {
                assert(x >> 2 == x / 4) by (bit_vector);
                assert(pow2(2) == 4) by (compute_only);
            } else if shift == 3 {
                assert(x >> 3 == x / 8) by (bit_vector);
                assert(pow2(3) == 8) by (compute_only);
            } else {
                assert(x >> shift == (x >> (sub(shift, 4) as $uN)) / 16) by (bit_vector)
                    requires
                        4 <= shift < <$uN>::BITS,
                ;
                calc!{ (==)
                    (x >> shift) as nat;
                        {}
                    ((x >> (sub(shift, 4) as $uN)) / 16) as nat;
                        { $name(x, (shift - 4) as $uN); }
                    (x as nat / pow2((shift - 4) as nat)) / 16;
                        {
                            lemma_pow2_pos((shift - 4) as nat);
                            lemma2_to64();
                            assert(pow2(4) == 16) by (compute_only);
                            lemma_div_denominator(x as int, pow2((shift - 4) as nat) as int, 16);
                        }
                    x as nat / (pow2((shift - 4) as nat) * pow2(4));
                        {
                            lemma_pow2_adds((shift - 4) as nat, 4);
                        }
                    x as nat / pow2(shift as nat);
                }
            }
        }
        }
    };
}

lemma_shr_is_div!(lemma_u128_shr_is_div, u128);
lemma_shr_is_div!(lemma_u64_shr_is_div, u64);
lemma_shr_is_div!(lemma_u32_shr_is_div, u32);
lemma_shr_is_div!(lemma_u16_shr_is_div, u16);
lemma_shr_is_div!(lemma_u8_shr_is_div, u8);
lemma_shr_is_div!(lemma_usize_shr_is_div, usize);

// Proofs of when a power of 2 fits in an unsigned type.
macro_rules! lemma_pow2_no_overflow {
    ($name:ident, $uN:ty) => {
        #[cfg(verus_keep_ghost)]
        verus! {
        #[doc = "Proof that 2^n does not overflow "]
        #[doc = stringify!($uN)]
        #[doc = " for an exponent n."]
        pub broadcast proof fn $name(n: nat)
            requires
                0 <= n < <$uN>::BITS,
            ensures
                0 < #[trigger] pow2(n) < <$uN>::MAX,
        {
            lemma_pow2_pos(n);
            lemma2_to64();
            lemma2_to64_rest();
        }
